if (( $# == 0 )); then echo '请先在访达中选中照片，再运行快捷操作。' >&2; exit 1; fi
/usr/bin/swift - "$@" <<'NIKON_SWIFT'
import AppKit
import ImageIO
import UniformTypeIdentifiers

import CoreLocation

var placeCache: [String:String] = [:]
let watermarkMarker = "WATERMARK"

func isWatermarkFileName(_ stem: String) -> Bool {
    stem.range(of:"-相框(?:-\\d+)?$", options:.regularExpression) != nil
}

func normalizeCommentText(_ text: String) -> String {
    guard text.contains("\0") else { return text }
    for code in ["UNICODE", "Unicode", "ASCII", "JIS"] where text.hasPrefix(code) {
        var rest = text.dropFirst(code.count)
        while rest.first == "\0" { rest = rest.dropFirst() }
        return rest.replacingOccurrences(of:"\0", with:"")
    }
    return text.replacingOccurrences(of:"\0", with:"")
}

func commentScore(_ text: String) -> Int {
    var score = 0
    for scalar in text.unicodeScalars {
        let value = scalar.value
        if value == 0xFFFD { score -= 20; continue }
        if value < 32 && value != 9 && value != 10 && value != 13 { score -= 5; continue }
        if (32...126).contains(value) { score += 5; continue }
        if (0x4E00...0x9FFF).contains(value) || (0x3400...0x4DBF).contains(value) || (0x3040...0x30FF).contains(value) || (0xAC00...0xD7AF).contains(value) { score += 4; continue }
        if scalar.properties.isAlphabetic { score += 1; continue }
        score -= 2
    }
    return score
}

func decodedUTF16Comment(_ payload: Data) -> String? {
    if payload.count >= 2 {
        let prefix = [UInt8](payload.prefix(2))
        if prefix == [0xFF, 0xFE] || prefix == [0xFE, 0xFF],
           let decoded = String(data:payload, encoding:.utf16) {
            let cleaned = normalizeCommentText(decoded)
            if !cleaned.isEmpty { return cleaned }
        }
    }
    let candidates = [String.Encoding.utf16LittleEndian, .utf16BigEndian].compactMap { encoding -> String? in
        guard let decoded = String(data:payload, encoding:encoding) else { return nil }
        let cleaned = normalizeCommentText(decoded)
        return cleaned.isEmpty ? nil : cleaned
    }
    return candidates.max(by:{ commentScore($0) < commentScore($1) })
}

func decodedExifUserComment(_ data: Data) -> String? {
    func text(_ data: Data, _ encodings: [String.Encoding]) -> String? {
        for encoding in encodings {
            if let decoded = String(data:data, encoding:encoding) {
                let cleaned = normalizeCommentText(decoded)
                if !cleaned.isEmpty { return cleaned }
            }
        }
        return nil
    }
    if data.count < 8 { return text(data, [.utf8, .isoLatin1]) ?? "" }
    let header = String(data:Data(data.prefix(8)), encoding:.ascii) ?? ""
    let payload = Data(data.dropFirst(8))
    if header.hasPrefix("UNICODE") { return decodedUTF16Comment(payload) }
    if header.hasPrefix("ASCII") || header.hasPrefix("JIS") || (header.count == 8 && header.allSatisfy { $0 == "\0" }) {
        return text(payload, [.utf8, .isoLatin1]) ?? ""
    }
    return text(data, [.utf8])
}

func exifCommentText(_ value: Any?) -> String? {
    if let text = value as? String { return normalizeCommentText(text) }
    if let data = value as? Data { return decodedExifUserComment(data) }
    return nil
}

func containsWatermarkMarker(_ value: Any?) -> Bool {
    exifCommentText(value)?.contains(watermarkMarker) == true
}

func userCommentWithMarker(_ value: Any?) -> Any {
    guard let text = exifCommentText(value) else {
        if let value = value { return value }
        return watermarkMarker
    }
    if text.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty { return watermarkMarker }
    if text.contains(watermarkMarker) { return text }
    return text.trimmingCharacters(in:.whitespacesAndNewlines) + "\n" + watermarkMarker
}

func colorSpaceNeedsSRGB(_ name: String?) -> Bool {
    guard let name = name else { return true }
    return ["kCGColorSpaceAdobeRGB1998", "kCGColorSpaceROMMRGB", "kCGColorSpaceWideGamutRGB"].contains(name)
}

func renderedColor(for photo: CGImage) -> (space: CGColorSpace, convertsToSRGB: Bool) {
    let srgb = CGColorSpace(name: CGColorSpace.sRGB)!
    guard let space = photo.colorSpace else { return (srgb, true) }
    let name = space.name as String?
    if colorSpaceNeedsSRGB(name) { return (srgb, true) }
    return (space, false)
}

func locationCaption(_ metadata:[String:Any]) -> String {
    guard let gps = metadata["{GPS}"] as? [String:Any],
          let lat = gps["Latitude"] as? Double, let lon = gps["Longitude"] as? Double,
          let ns = gps["LatitudeRef"] as? String, ["N","S"].contains(ns),
          let ew = gps["LongitudeRef"] as? String, ["E","W"].contains(ew),
          abs(lat) <= 90, abs(lon) <= 180 else { return "" }
    let point = CLLocation(latitude:abs(lat)*(ns == "S" ? -1 : 1), longitude:abs(lon)*(ew == "W" ? -1 : 1))
    let key = "\(point.coordinate.latitude),\(point.coordinate.longitude)"
    if let cached = placeCache[key] { return cached }
    let english = Locale(identifier:"en_US")
    let coder = CLGeocoder()
    var caption = ""
    var finished = false
    coder.reverseGeocodeLocation(point, preferredLocale:english) { results,_ in
        if let place = results?.first, let code = place.isoCountryCode,
           let country = english.localizedString(forRegionCode:code),
           let city = place.locality?.trimmingCharacters(in:.whitespacesAndNewlines), !city.isEmpty,
           city.range(of:"[^\\p{Latin}\\p{M}\\p{P}\\p{Z}0-9]",options:.regularExpression) == nil {
            let displayCountry = code == "CN" ? "China" : country
            caption = city.caseInsensitiveCompare(displayCountry) == .orderedSame ? city : "\(displayCountry), \(city)"
        }
        finished = true
    }
    let deadline = Date().addingTimeInterval(3)
    while !finished && Date() < deadline { RunLoop.current.run(until:Date().addingTimeInterval(0.05)) }
    if !finished { coder.cancelGeocode() }
    if !caption.isEmpty { placeCache[key] = caption }
    return caption
}

func shutterString(_ t: Double) -> String {
    let denominators: [Double] = [1.0, 1.3, 1.6, 2.0, 2.5, 3.0, 4.0, 5.0, 6.0, 8.0, 10.0, 13.0, 15.0, 20.0, 25.0, 30.0, 40.0, 50.0, 60.0, 80.0, 100.0, 125.0, 160.0, 200.0, 250.0, 320.0, 400.0, 500.0, 640.0, 800.0, 1000.0, 1250.0, 1600.0, 2000.0, 2500.0, 3200.0, 4000.0, 5000.0, 6400.0, 8000.0]
    let times: [Double] = [1.0, 1.3, 1.6, 2.0, 2.5, 3.0, 4.0, 5.0, 6.0, 8.0, 10.0, 13.0, 15.0, 20.0, 25.0, 30.0]
    func format(_ v: Double) -> String {
        if abs(v - v.rounded()) < 0.0005 { return String(Int(v.rounded())) }
        let one = (v * 10).rounded() / 10
        return one == one.rounded() ? String(Int(one.rounded())) : String(format: "%.1f", one)
    }
    if t >= 1 {
        let near = times.min(by: { abs($0 - t) < abs($1 - t) })!
        if abs(near - t) <= near * 0.02 + 0.005 { return "\(format(near)) s" }
        return "\(format(t)) s"
    }
    let r = 1 / t
    let near = denominators.min(by: { abs($0 - r) < abs($1 - r) })!
    if abs(near - r) <= near * 0.02 + 0.005 { return "1/\(format(near)) s" }
    return "1/\(format(r)) s"
}

for path in CommandLine.arguments.dropFirst() {
    do {
        let url = URL(fileURLWithPath: path)
        if isWatermarkFileName(url.deletingPathExtension().lastPathComponent) {
            FileHandle.standardError.write(Data(("跳过：\(path)（已经是带水印的文件）\n").utf8))
            continue
        }
        guard let source = CGImageSourceCreateWithURL(url as CFURL, nil),
              let meta = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [String: Any],
              let w = meta["PixelWidth"] as? Int, let h = meta["PixelHeight"] as? Int else { throw CocoaError(.fileReadCorruptFile) }
        let srcExif = meta[kCGImagePropertyExifDictionary as String] as? [String: Any] ?? [:]
        if containsWatermarkMarker(srcExif[kCGImagePropertyExifUserComment as String]) {
            FileHandle.standardError.write(Data(("跳过：\(path)（EXIF 标记已带水印）\n").utf8))
            continue
        }
        let place = locationCaption(meta)
        let options: [String: Any] = [kCGImageSourceCreateThumbnailFromImageAlways as String: true, kCGImageSourceCreateThumbnailWithTransform as String: true, kCGImageSourceThumbnailMaxPixelSize as String: max(w,h)]
        guard let photo = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) else { throw CocoaError(.fileReadCorruptFile) }
        let width = CGFloat(photo.width), height = CGFloat(photo.height)
        let edge = max(1, (width * 0.022).rounded())
        let band = max(8, (width * 0.079).rounded())
        let color = renderedColor(for: photo)
        guard let ctx = CGContext(data:nil,width:Int(width+2*edge),height:Int(height+band+edge),bitsPerComponent:8,bytesPerRow:0,space:color.space,bitmapInfo:CGImageAlphaInfo.noneSkipLast.rawValue) else { throw CocoaError(.fileWriteUnknown) }
        ctx.setFillColor(CGColor(gray:1,alpha:1))
        ctx.fill(CGRect(x:0,y:0,width:width+2*edge,height:height+band+edge))
        ctx.draw(photo,in:CGRect(x:edge,y:band,width:width,height:height))
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = NSGraphicsContext(cgContext:ctx, flipped:false)
        let ex = meta["{Exif}"] as? [String:Any] ?? [:]
        let model = ((meta["{TIFF}"] as? [String:Any])?["Model"] as? String ?? "").trimmingCharacters(in:.whitespacesAndNewlines)
        var fields = [String]()
        if let f = ex["FocalLength"] as? NSNumber { fields.append("\(f) mm") }
        if let f = ex["FNumber"] as? NSNumber { fields.append("f/\(f)") }
        if let t = ex["ExposureTime"] as? Double, t > 0 { fields.append(shutterString(t)) }
        if let iso = (ex["ISOSpeedRatings"] as? [NSNumber])?.first { fields.append("ISO \(iso)") }
        func label(_ value:String, x:CGFloat, center:CGFloat, limit:CGFloat, size:CGFloat, bold:Bool) {
            let text = value as NSString
            var attrs: [NSAttributedString.Key:Any] = [.font:NSFont.systemFont(ofSize:size,weight:bold ? .semibold : .regular),.foregroundColor:bold ? NSColor.black : NSColor.darkGray]
            let scale = min(1, limit / max(1,text.size(withAttributes:attrs).width))
            attrs[.font] = NSFont.systemFont(ofSize:size*scale,weight:bold ? .semibold : .regular)
            text.draw(at:NSPoint(x:x,y:center-text.size(withAttributes:attrs).height/2),withAttributes:attrs)
        }
        func drawMark(_ encoded: String, x: CGFloat, center: CGFloat, markHeight: CGFloat) {
            let data = Data(base64Encoded: encoded)!
            let source = CGImageSourceCreateWithData(data as CFData, nil)!
            let raw = CGImageSourceCreateImageAtIndex(source, 0, nil)!
            let image = raw.width == 1240 ? raw.cropping(to:CGRect(x:0,y:0,width:372,height:149))! : raw
            let width = markHeight * CGFloat(image.width) / CGFloat(image.height)
            ctx.interpolationQuality = .high
            ctx.draw(image, in: CGRect(x:x,y:center-markHeight/2,width:width,height:markHeight))
        }
        let left = edge + width*0.016
        let info = edge + width*(place.isEmpty ? 0.75 : 0.65)
        let logo = info - width*0.078
        let lens = (ex["LensModel"] as? String ?? "").trimmingCharacters(in:.whitespacesAndNewlines)
        let brands: [([String],CGFloat,String)] = [
            (["NIKKOR"],4.387096774193548,""),
    (["Viltrox", "唯卓仕"], 5.419354838709677, ""),
    (["TTArtisan", "铭匠"], 7.317073170731708, ""),
    (["7Artisans", "七工匠"], 5.431578947368421, ""),
    (["Sigma", "适马"], 4.25531914893617, ""),
    (["Tamron", "腾龙"], 6.091836734693878, ""),
    (["Laowa", "Venus Optics", "老蛙"], 3.8333333333333335, ""),
    (["Samyang", "三阳"], 4.285714285714286, ""),
    (["Sirui", "思锐"], 3.7254901960784315, ""),
    (["Meike", "美科"], 3.3410852713178296, ""),
    (["Voigtländer", "Voigtlaender", "Voigtlander", "福伦达"], 5.357142857142857, ""),
    (["Tokina", "图丽"], 6.666666666666667, "")
        ]
        let make = ex["LensMake"] as? String ?? ""
        func brandRange(_ name:String, in value:String) -> Range<String.Index>? {
            let pattern = "(?<![A-Za-z0-9])" + NSRegularExpression.escapedPattern(for:name) + "(?![A-Za-z])"
            return value.range(of:pattern,options:[.regularExpression,.caseInsensitive])
        }
        let selected = [lens,make].compactMap { value in
            brands.first { brand in brand.0.contains { brandRange($0,in:value) != nil } }
        }.first
        let nikonLens = !lens.isEmpty && ["NIKON", "NIKON CORPORATION"].contains(make.trimmingCharacters(in:.whitespacesAndNewlines).uppercased())
        let lensBrand = selected ?? (nikonLens ? brands.first : nil)
        if let (names,aspect,data) = lensBrand {
            let markHeight = min(NSFont.systemFont(ofSize:width*0.018).capHeight,width*0.12/aspect)
            drawMark(data,x:left,center:band*0.65,markHeight:markHeight)
            var specs = lens
            for name in names {
                if let range = brandRange(name,in:specs) { specs.removeSubrange(range) }
            }
            let start = left + markHeight*aspect + width*0.0075
            label(specs.trimmingCharacters(in:.whitespaces),x:start,center:band*0.65,limit:logo-start-edge,size:width*0.018,bold:false)
        } else {
            label(lens,x:left,center:band*0.65,limit:logo-left-edge,size:width*0.018,bold:false)
        }
        let cameraCenter = band*(lens.isEmpty && selected == nil ? 0.5 : 0.33)
        let maker = ((meta["{TIFF}"] as? [String:Any])?["Make"] as? String ?? "").uppercased()
        let nikon = maker.contains("NIKON") || model.uppercased().hasPrefix("NIKON")
        let modelX = nikon ? left + width*0.048 : left
        if nikon {
            drawMark("",x:left,center:cameraCenter,markHeight:width*0.0115)
        }
        let camera = model.uppercased().replacingOccurrences(of:"^NIKON",with:"",options:.regularExpression).filter { $0.isLetter || $0.isNumber }
        if nikon && ["Z62","Z6II","Z6Ⅱ"].contains(camera) {
            drawMark("",x:modelX,center:cameraCenter,markHeight:width*0.0115)
        } else if nikon && camera == "Z30" {
            drawMark("",x:modelX,center:cameraCenter,markHeight:width*0.0115)
        } else if nikon && camera.hasPrefix("Z") && camera.count > 1 {
            drawMark("",x:modelX,center:cameraCenter,markHeight:width*0.0115)
            let suffix = model.replacingOccurrences(of:"(?i)^\\s*(?:NIKON\\s*)?Z[\\s_-]*",with:"",options:.regularExpression).replacingOccurrences(of:"_3",with:"III").replacingOccurrences(of:"_2",with:"II")
            label(suffix,x:modelX+width*0.018,center:cameraCenter,limit:width*0.45,size:width*0.015,bold:false)
        } else {
            label(model.replacingOccurrences(of:"^NIKON\\s*",with:"",options:[.regularExpression,.caseInsensitive]),x:modelX,center:cameraCenter,limit:width*0.5,size:width*0.015,bold:false)
        }
        if nikon {
            drawMark("",x:logo,center:band*0.5,markHeight:width*0.043)
        }
        ctx.setFillColor(CGColor(gray:0.80,alpha:1))
        ctx.fill(CGRect(x:info-width*0.016,y:band*0.20,width:max(1,width*0.0008),height:band*0.60))
        let stamp = ex["DateTimeOriginal"] as? String ?? ""
        let date = String(stamp.prefix(10)).replacingOccurrences(of:":",with:"-") + String(stamp.dropFirst(10).prefix(6))
        let detail = [date,place].filter { !$0.isEmpty }.joined(separator:"   ·   ")
        label(fields.joined(separator:"  "),x:info,center:band*(detail.isEmpty ? 0.5 : 0.63),limit:width*0.24,size:width*0.018,bold:true)
        label(detail,x:info,center:band*0.29,limit:edge+width*0.99-info,size:width*0.015,bold:false)
        NSGraphicsContext.restoreGraphicsState()
        let data = NSMutableData()
        guard let image = ctx.makeImage(), let dest = CGImageDestinationCreateWithData(data, UTType.jpeg.identifier as CFString,1,nil) else { throw CocoaError(.fileWriteUnknown) }
        var outMeta = meta
        outMeta[kCGImagePropertyOrientation as String] = 1
        outMeta[kCGImagePropertyPixelWidth as String] = nil
        outMeta[kCGImagePropertyPixelHeight as String] = nil
        outMeta[kCGImagePropertyProfileName as String] = nil
        if color.convertsToSRGB {
            for key in Array(outMeta.keys) where key.uppercased().contains("ICC") { outMeta.removeValue(forKey: key) }
        }
        outMeta[kCGImagePropertyColorModel as String] = nil
        outMeta[kCGImagePropertyDepth as String] = nil
        outMeta[kCGImagePropertyDPIWidth as String] = nil
        outMeta[kCGImagePropertyDPIHeight as String] = nil
        outMeta[kCGImagePropertyHasAlpha as String] = nil
        var outExif = (outMeta[kCGImagePropertyExifDictionary as String] as? [String: Any]) ?? [:]
        outExif[kCGImagePropertyExifUserComment as String] = userCommentWithMarker(outExif[kCGImagePropertyExifUserComment as String])
        outMeta[kCGImagePropertyExifDictionary as String] = outExif
        outMeta[kCGImageDestinationLossyCompressionQuality as String] = 0.96
        CGImageDestinationAddImage(dest,image,outMeta as CFDictionary)
        guard CGImageDestinationFinalize(dest) else { throw CocoaError(.fileWriteUnknown) }
        var n = 1
        while true {
            let suffix = n == 1 ? "" : "-\(n)"
            let out = URL(fileURLWithPath:url.deletingPathExtension().path+"-相框"+suffix+".jpg")
            do { try (data as Data).write(to:out,options:.withoutOverwriting); break }
            catch let error as NSError where error.domain == NSCocoaErrorDomain && error.code == NSFileWriteFileExistsError { n += 1 }
        }
    } catch {
        let message = "跳过无法处理的文件：\(path)（\(error.localizedDescription)）\n"
        FileHandle.standardError.write(Data(message.utf8))
    }
}

NIKON_SWIFT